head.b:skin:
:root {
  --bg-body: #06090f;
  --bg-card: rgba(18, 24, 38, 0.7);
  --border-color: rgba(255, 255, 255, 0.08);
  --primary: #38bdf8;
  --accent: #f59e0b;
  --danger: #ef4444;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --font: 'Plus Jakarta Sans', sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body, html {
  background-color: var(--bg-body) !important;
  color: var(--text-main) !important;
  font-family: var(--font);
  line-height: 1.6;
  min-height: 100vh;
  overflow-x: hidden;
}
a { color: inherit; text-decoration: none; }

/* Top Breaking News Bar */
.ticker-bar {
  background: #020408;
  border-bottom: 1px solid var(--border-color);
  padding: 0.4rem 1.5rem;
  font-size: 0.8rem;
}
.ticker-inner {
  max-width: 1240px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 1rem;
}
.ticker-badge {
  background: var(--danger);
  color: #fff;
  font-weight: 800;
  font-size: 0.65rem;
  padding: 2px 8px;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  display: flex;
  align-items: center;
  gap: 5px;
}
.ticker-badge::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #fff;
  animation: pulse 1.2s infinite;
}
@keyframes pulse { 0% { opacity: 0.3; } 50% { opacity: 1; } 100% { opacity: 0.3; } }
.ticker-text {
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Main Navigation Header */
.navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(6, 9, 15, 0.92);
  backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--border-color);
  padding: 0.9rem 1.5rem;
}
.nav-container {
  max-width: 1240px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.brand {
  display: flex;
  align-items: center;
  gap: 0.85rem;
}
.brand-avatar {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: linear-gradient(135deg, #38bdf8, #f59e0b);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  color: #06090f;
  font-size: 1.2rem;
  box-shadow: 0 0 20px rgba(56, 189, 248, 0.4);
}
.brand-info h1 {
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: #fff;
  line-height: 1.2;
}
.brand-domain {
  font-size: 0.75rem;
  color: var(--primary);
  font-family: monospace;
  letter-spacing: 0.05em;
}

.header-socials {
  display: flex;
  align-items: center;
  gap: 0.65rem;
}
.social-btn {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.05rem;
  color: var(--text-main);
  transition: all 0.25s ease;
}
.social-btn:hover { transform: translateY(-2px); color: #fff; }
.social-btn.yt:hover { background: #ff0000; border-color: #ff0000; }
.social-btn.fb:hover { background: #1877f2; border-color: #1877f2; }
.social-btn.ig:hover { background: #d6249f; border-color: #d6249f; }
.social-btn.th:hover { background: #000; border-color: #fff; }

/* Category Strip (Prothom Alo style subnav) */
.category-strip {
  background: rgba(18, 24, 38, 0.6);
  border-bottom: 1px solid var(--border-color);
  padding: 0.65rem 1.5rem;
}
.category-container {
  max-width: 1240px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 1.75rem;
  overflow-x: auto;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
  white-space: nowrap;
}
.category-container a:hover, .category-container a.active {
  color: var(--primary);
}

/* Main Container */
.layout-wrapper {
  max-width: 1240px;
  margin: 2rem auto;
  padding: 0 1.5rem;
}

/* Prothom Alo Newsfeed Grid */
.news-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
  gap: 2rem;
}

/* News Article Card */
.news-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
  cursor: pointer;
}
.news-card:hover {
  transform: translateY(-5px);
  border-color: rgba(56, 189, 248, 0.4);
  box-shadow: 0 15px 35px -10px rgba(0, 0, 0, 0.7);
}

.news-thumb-wrap {
  position: relative;
  width: 100%;
  padding-top: 56.25%;
  background: #090e17;
  overflow: hidden;
}
.news-thumb-wrap img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}
.news-card:hover .news-thumb-wrap img {
  transform: scale(1.05);
}

.news-tag {
  position: absolute;
  top: 12px;
  left: 12px;
  background: rgba(6, 9, 15, 0.85);
  border: 1px solid rgba(255, 255, 255, 0.15);
  backdrop-filter: blur(8px);
  color: var(--primary);
  font-size: 0.7rem;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 6px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.news-content {
  padding: 1.4rem;
  display: flex;
  flex-direction: column;
  flex: 1;
  justify-content: space-between;
}
.news-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: #fff;
  line-height: 1.4;
  margin-bottom: 0.75rem;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.news-card:hover .news-title {
  color: var(--primary);
}
.news-snippet {
  font-size: 0.88rem;
  color: var(--text-muted);
  line-height: 1.6;
  margin-bottom: 1rem;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.news-meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.78rem;
  color: #64748b;
  border-top: 1px solid var(--border-color);
  padding-top: 0.75rem;
}
.news-meta span.author {
  color: var(--accent);
  font-weight: 600;
}

/* Single Article Page */
.single-page {
  max-width: 900px;
  margin: 0 auto;
}
.single-page h1 {
  font-size: 2.2rem;
  font-weight: 800;
  margin-bottom: 0.75rem;
  color: #fff;
}
.single-body {
  font-size: 1.05rem;
  color: #cbd5e1;
  line-height: 1.85;
  margin-top: 1.5rem;
}
.single-body iframe {
  width: 100% !important;
  border-radius: 16px;
  border: 0;
  margin: 1.5rem 0;
}

/* Footer */
footer {
  border-top: 1px solid var(--border-color);
  background: #04060a;
  padding: 3rem 1.5rem;
  text-align: center;
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-top: 4rem;
}

@media (max-width: 768px) {
  .news-grid { grid-template-columns: 1fr; }
  .navbar { padding: 0.75rem 1rem; }
  .brand-info h1 { font-size: 1.1rem; }
  .header-socials { gap: 0.35rem; }
  .social-btn { width: 32px; height: 32px; font-size: 0.95rem; }
}
